package com.universe.community.dto.response; import com.universe.community.entity.Comment; import lombok.AllArgsConstructor; import lombok.Getter; import java.time.LocalDateTime; @Getter @AllArgsConstructor public class CommentResponse { private Long commentId; private Long postId; private Long authorId; private String authorName; private String content; private boolean anonymous; private boolean postAuthor; private Long parentCommentId; private LocalDateTime createdAt; private LocalDateTime updatedAt; public static CommentResponse from(Comment c){boolean anonymous=Boolean.TRUE.equals(c.getIsAnonymous());boolean postAuthor=c.getPost().getUser().getId().equals(c.getUser().getId());return new CommentResponse(c.getId(),c.getPost().getId(),anonymous?null:c.getUser().getId(),anonymous?"익명":c.getUser().getNickname(),c.getContent(),anonymous,postAuthor,c.getParentComment()==null?null:c.getParentComment().getId(),c.getCreatedAt(),c.getUpdatedAt());}}
